          status: "QUEUED",
          deliveryState: "ATTEMPTING",
          dispatchedAt: new Date(),
          attemptedAt: new Date(),
          sentAt: null,
        },
        {
          status: "QUEUED",
          deliveryState: "READY",
          dispatchedAt: new Date(),
          attemptedAt: null,
          sentAt: null,
        },
        {
          status: "FAILED",
          deliveryState: "UNCERTAIN",
          dispatchedAt: new Date(),
          attemptedAt: new Date(),
          sentAt: null,
        },
      ],
    },
